// Quantification post-processing with tximport and SummarizedExperiment
//

include { CUSTOM_TX2GENE   } from 'nf-core/custom/tx2gene'
include { TXIMETA_TXIMPORT } from 'nf-core/tximeta/tximport'

include { SUMMARIZEDEXPERIMENT_SUMMARIZEDEXPERIMENT as SE_GENE_UNIFIED       } from 'nf-core/summarizedexperiment/summarizedexperiment'
include { SUMMARIZEDEXPERIMENT_SUMMARIZEDEXPERIMENT as SE_TRANSCRIPT_UNIFIED } from 'nf-core/summarizedexperiment/summarizedexperiment'

workflow QUANT_TXIMPORT_SUMMARIZEDEXPERIMENT {
    take:
    samplesheet           // channel: [ val(meta), /path/to/samplesheet ]
    quant_results         // channel: [ val(meta), /path/to/results ] - per-sample quant files
    gtf                   // channel: /path/to/genome.gtf
    gtf_id_attribute      //     val: GTF gene ID attribute
    gtf_extra_attribute   //     val: GTF alternative gene attribute (e.g. gene_name)
    quant_type            //     val: 'salmon', 'kallisto', or 'rsem'
    skip_merge            //    bool: skip cross-sample merging, run tximport per-sample

    main:

    //
    // Create tx2gene mapping from GTF + a single sample's quantification files.
    // tx2gene only uses quant files to discover which GTF attribute corresponds
    // to transcript IDs, so a single sample suffices. This assumes all samples
    // were quantified against the same transcriptome, avoiding the need to run
    // tx2gene independently per sample. If a use case arises requiring mixed
    // transcriptomes, this will need to be revisited.
    //
    // The sample is selected by sorting on the staged results name so the same
    // one is chosen on every run, keeping the CUSTOM_TX2GENE cache key stable
    // across -resume. Picking by arrival order would vary between runs and
    // invalidate the cache for tx2gene and everything downstream of it. The
    // empty-list guard keeps tx2gene from running when no quant results are
    // supplied, since toSortedList still emits an empty list in that case.
    //
    ch_tx2gene_quants = quant_results
        .toSortedList { a, b -> a[1].name <=> b[1].name }
        .filter { sorted -> sorted.size() > 0 }
        .map { sorted -> [ [:], sorted.first()[1] ] }

    CUSTOM_TX2GENE (
        gtf.map { gtf_file -> [ [:], gtf_file ] },
        ch_tx2gene_quants,
        quant_type,
        gtf_id_attribute,
        gtf_extra_attribute
    )

    //
    // Import and summarize quantifications with tximport
    // In per-sample mode, run once per sample instead of collecting all
    //
    // Sorted by name for a stable cache key; the R script derives sample
    // identity from staged file names, not list position. Filtered to
    // skip TXIMETA_TXIMPORT when there are no samples, since
    // toSortedList() emits [] rather than nothing on an empty channel.
    //
    ch_tximport_input = skip_merge
        ? quant_results
        : quant_results
            .toSortedList { a, b -> a[1].name <=> b[1].name }
            .filter { sorted -> sorted.size() > 0 }
            .map { sorted -> [ ['id': 'all_samples'], sorted.collect { it[1] } ] }

    TXIMETA_TXIMPORT (
        ch_tximport_input,
        CUSTOM_TX2GENE.out.tx2gene,
        quant_type
    )

    //
    // Build SummarizedExperiment objects (only when merging)
    //
    ch_merged_gene_rds       = channel.empty()
    ch_merged_transcript_rds = channel.empty()

    if (!skip_merge) {
        //
        // Build gene-level SummarizedExperiment
        //
        ch_gene_unified = TXIMETA_TXIMPORT.out.counts_gene
            .join(TXIMETA_TXIMPORT.out.counts_gene_length_scaled, failOnMismatch: true, failOnDuplicate: true)
            .join(TXIMETA_TXIMPORT.out.counts_gene_scaled, failOnMismatch: true, failOnDuplicate: true)
            .join(TXIMETA_TXIMPORT.out.lengths_gene, failOnMismatch: true, failOnDuplicate: true)
            .join(TXIMETA_TXIMPORT.out.tpm_gene, failOnMismatch: true, failOnDuplicate: true)
            .map { row -> tuple(row[0], row.tail()) }

        SE_GENE_UNIFIED (
            ch_gene_unified,
            CUSTOM_TX2GENE.out.tx2gene,
            samplesheet
        )

        //
        // Build transcript-level SummarizedExperiment
        //
        ch_transcript_unified = TXIMETA_TXIMPORT.out.counts_transcript
            .join(TXIMETA_TXIMPORT.out.lengths_transcript, failOnMismatch: true, failOnDuplicate: true)
            .join(TXIMETA_TXIMPORT.out.tpm_transcript, failOnMismatch: true, failOnDuplicate: true)
            .map { row -> tuple(row[0], row.tail()) }

        SE_TRANSCRIPT_UNIFIED (
            ch_transcript_unified,
            TXIMETA_TXIMPORT.out.tx2gene_augmented,
            samplesheet
        )

        ch_merged_gene_rds       = SE_GENE_UNIFIED.out.rds
        ch_merged_transcript_rds = SE_TRANSCRIPT_UNIFIED.out.rds
    }

    emit:
    tx2gene                   = CUSTOM_TX2GENE.out.tx2gene                     // channel: [ val(meta), tx2gene.tsv ]
    tx2gene_augmented         = TXIMETA_TXIMPORT.out.tx2gene_augmented         // channel: [ val(meta), tx2gene_augmented.tsv ]

    tpm_gene                  = TXIMETA_TXIMPORT.out.tpm_gene                  //    path: *gene_tpm.tsv
    counts_gene               = TXIMETA_TXIMPORT.out.counts_gene               //    path: *gene_counts.tsv
    lengths_gene              = TXIMETA_TXIMPORT.out.lengths_gene              //    path: *gene_lengths.tsv
    counts_gene_length_scaled = TXIMETA_TXIMPORT.out.counts_gene_length_scaled //    path: *gene_counts_length_scaled.tsv
    counts_gene_scaled        = TXIMETA_TXIMPORT.out.counts_gene_scaled        //    path: *gene_counts_scaled.tsv
    tpm_transcript            = TXIMETA_TXIMPORT.out.tpm_transcript            //    path: *transcript_tpm.tsv
    counts_transcript         = TXIMETA_TXIMPORT.out.counts_transcript         //    path: *transcript_counts.tsv
    lengths_transcript        = TXIMETA_TXIMPORT.out.lengths_transcript        //    path: *transcript_lengths.tsv

    merged_gene_rds           = ch_merged_gene_rds                             //    path: *.rds
    merged_transcript_rds     = ch_merged_transcript_rds                       //    path: *.rds
}

process {
    withName: '.*:QUANT_TXIMPORT_SUMMARIZEDEXPERIMENT:CUSTOM_TX2GENE' {
        ext.prefix = { "${quant_type}.merged" }
    }

    withName: '.*:QUANT_TXIMPORT_SUMMARIZEDEXPERIMENT:TXIMETA_TXIMPORT' {
        ext.prefix = { "${quant_type}.merged" }
    }

    withName: '.*:QUANT_TXIMPORT_SUMMARIZEDEXPERIMENT:SE_GENE_UNIFIED' {
        ext.prefix = { "${meta.id}_gene" }
        ext.args = '--assay_names counts,counts_length_scaled,counts_scaled,lengths,tpm'
    }

    withName: '.*:QUANT_TXIMPORT_SUMMARIZEDEXPERIMENT:SE_TRANSCRIPT_UNIFIED' {
        ext.prefix = { "${meta.id}_transcript" }
        ext.args = '--assay_names counts,lengths,tpm'
    }
}

nextflow_workflow {

    name "Test Workflow QUANT_TXIMPORT_SUMMARIZEDEXPERIMENT"
    script "../main.nf"
    config "./nextflow.config"
    workflow "QUANT_TXIMPORT_SUMMARIZEDEXPERIMENT"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/quant_tximport_summarizedexperiment"

    tag "custom/tx2gene"
    tag "tximeta/tximport"
    tag "summarizedexperiment/summarizedexperiment"
    tag "untar"

    test("salmon") {

        setup {
            run("UNTAR") {
                script "../../../../modules/nf-core/untar/main.nf"
                process {
                    """
                    input[0] = channel.of([
                        [ id: 'salmon_results' ],
                        file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/salmon_results.tar.gz', checkIfExists: true)
                    ])
                    """
                }
            }
        }

        when {
            workflow {
                """
                input[0] = [
                    [ id: 'samplesheet' ],
                    file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/samplesheet.csv', checkIfExists: true)
                ]
                input[1] = UNTAR.out.untar.flatMap { meta, dir ->
                    def entries = []
                    dir.toFile().eachDir { d ->
                        entries << [[ id: d.name ], d.toPath()]
                    }
                    entries
                }
                input[2] = channel.of(file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/genome_gfp.gtf', checkIfExists: true))
                input[3] = 'gene_id'
                input[4] = 'gene_name'
                input[5] = 'salmon'
                input[6] = false
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                        file(workflow.out.merged_gene_rds[0][1]).name,
                        file(workflow.out.merged_transcript_rds[0][1]).name,
                        workflow.out.counts_gene,
                        workflow.out.counts_gene_length_scaled,
                        workflow.out.counts_gene_scaled,
                        workflow.out.lengths_gene,
                        workflow.out.lengths_transcript,
                        workflow.out.tpm_gene,
                        workflow.out.tpm_transcript,
                        workflow.out.counts_transcript,
                        workflow.out.tx2gene,
                        workflow.out.tx2gene_augmented
                    ).match()
                }
            )
        }
    }

    test("salmon - transcript absent from GTF") {

        setup {
            run("UNTAR") {
                script "../../../../modules/nf-core/untar/main.nf"
                process {
                    """
                    input[0] = channel.of([
                        [ id: 'salmon_results' ],
                        file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/salmon_results.tar.gz', checkIfExists: true)
                    ])
                    """
                }
            }
        }

        when {
            workflow {
                """
                input[0] = [
                    [ id: 'samplesheet' ],
                    file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/samplesheet.csv', checkIfExists: true)
                ]
                // Append a row for a transcript absent from the GTF to each sample's quant.sf,
                // simulating e.g. a spike-in or a transcript_fasta sequence not derived from the
                // GTF. Regression test for SE_TRANSCRIPT_UNIFIED failing on exactly this case.
                // The copy keeps the original directory basename (tximport derives sample
                // identity from it, not from meta.id) - only the parent changes.
                input[1] = UNTAR.out.untar.flatMap { meta, dir ->
                    def entries = []
                    dir.toFile().eachDir { d ->
                        def copyDir = file("\${workDir}/\${d.name}_orphan/\${d.name}")
                        copyDir.mkdirs()
                        file("\${copyDir}/quant.sf").text = new File(d, 'quant.sf').text + "ORPHAN_TX_FIXTURE\\t500\\t450.000\\t0.000000\\t0.000\\n"
                        entries << [[ id: d.name ], copyDir]
                    }
                    entries
                }
                input[2] = channel.of(file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/genome_gfp.gtf', checkIfExists: true))
                input[3] = 'gene_id'
                input[4] = 'gene_name'
                input[5] = 'salmon'
                input[6] = false
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                // Present in transcript-level output (with its identity self-mapping)...
                { assert file(workflow.out.counts_transcript[0][1]).text.contains('ORPHAN_TX_FIXTURE') },
                { assert file(workflow.out.tx2gene_augmented[0][1]).text.contains('ORPHAN_TX_FIXTURE') },
                // ...but excluded from gene-level output, since it isn't a real gene.
                { assert !file(workflow.out.counts_gene[0][1]).text.contains('ORPHAN_TX_FIXTURE') }
            )
        }
    }

    test("kallisto") {

        setup {
            run("UNTAR") {
                script "../../../../modules/nf-core/untar/main.nf"
                process {
                    """
                    input[0] = channel.of([
                        [ id: 'kallisto_results' ],
                        file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/kallisto_results.tar.gz', checkIfExists: true)
                    ])
                    """
                }
            }
        }

        when {
            workflow {
                """
                input[0] = [
                    [ id: 'samplesheet' ],
                    file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/samplesheet.csv', checkIfExists: true)
                ]
                input[1] = UNTAR.out.untar.flatMap { meta, dir ->
                    def entries = []
                    dir.toFile().eachDir { d ->
                        entries << [[ id: d.name ], d.toPath()]
                    }
                    entries
                }
                input[2] = channel.of(file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/genome_gfp.gtf', checkIfExists: true))
                input[3] = 'gene_id'
                input[4] = 'gene_name'
                input[5] = 'kallisto'
                input[6] = false
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                        file(workflow.out.merged_gene_rds[0][1]).name,
                        file(workflow.out.merged_transcript_rds[0][1]).name,
                        workflow.out.counts_gene,
                        workflow.out.counts_gene_length_scaled,
                        workflow.out.counts_gene_scaled,
                        workflow.out.lengths_gene,
                        workflow.out.lengths_transcript,
                        workflow.out.tpm_gene,
                        workflow.out.tpm_transcript,
                        workflow.out.counts_transcript,
                        workflow.out.tx2gene,
                        workflow.out.tx2gene_augmented
                    ).match()
                }
            )
        }
    }

    test("rsem") {

        setup {
            run("UNTAR") {
                script "../../../../modules/nf-core/untar/main.nf"
                process {
                    """
                    input[0] = channel.of([
                        [ id: 'rsem_results' ],
                        file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/rsem_results.tar.gz', checkIfExists: true)
                    ])
                    """
                }
            }
        }

        when {
            workflow {
                """
                input[0] = [
                    [ id: 'samplesheet' ],
                    file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/samplesheet.csv', checkIfExists: true)
                ]
                input[1] = UNTAR.out.untar.flatMap { meta, dir ->
                    def entries = []
                    dir.toFile().eachFileRecurse { f ->
                        if (f.name.endsWith('.isoforms.results')) {
                            entries << [[ id: f.parentFile.name ], f.toPath()]
                        }
                    }
                    entries
                }
                input[2] = channel.of(file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/genome_gfp.gtf', checkIfExists: true))
                input[3] = 'gene_id'
                input[4] = 'gene_name'
                input[5] = 'rsem'
                input[6] = false
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                        file(workflow.out.merged_gene_rds[0][1]).name,
                        file(workflow.out.merged_transcript_rds[0][1]).name,
                        workflow.out.counts_gene,
                        workflow.out.counts_gene_length_scaled,
                        workflow.out.counts_gene_scaled,
                        workflow.out.lengths_gene,
                        workflow.out.lengths_transcript,
                        workflow.out.tpm_gene,
                        workflow.out.tpm_transcript,
                        workflow.out.counts_transcript,
                        workflow.out.tx2gene,
                        workflow.out.tx2gene_augmented
                    ).match()
                }
            )
        }
    }

    test("salmon - stub") {

        options "-stub"

        when {
            workflow {
                """
                input[0] = [
                    [ id: 'samplesheet' ],
                    file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/samplesheet.csv', checkIfExists: true)
                ]
                input[1] = channel.of(
                    [[ id: 'sample1' ], file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/genome_gfp.gtf', checkIfExists: true)]
                )
                input[2] = channel.of(file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/genome_gfp.gtf', checkIfExists: true))
                input[3] = 'gene_id'
                input[4] = 'gene_name'
                input[5] = 'salmon'
                input[6] = false
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(workflow.out).match() }
            )
        }
    }

    test("kallisto - stub") {

        options "-stub"

        when {
            workflow {
                """
                input[0] = [
                    [ id: 'samplesheet' ],
                    file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/samplesheet.csv', checkIfExists: true)
                ]
                input[1] = channel.of(
                    [[ id: 'sample1' ], file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/genome_gfp.gtf', checkIfExists: true)]
                )
                input[2] = channel.of(file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/genome_gfp.gtf', checkIfExists: true))
                input[3] = 'gene_id'
                input[4] = 'gene_name'
                input[5] = 'kallisto'
                input[6] = false
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(workflow.out).match() }
            )
        }
    }

    test("rsem - stub") {

        options "-stub"

        when {
            workflow {
                """
                input[0] = [
                    [ id: 'samplesheet' ],
                    file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/samplesheet.csv', checkIfExists: true)
                ]
                input[1] = channel.of(
                    [[ id: 'sample1' ], file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/genome_gfp.gtf', checkIfExists: true)]
                )
                input[2] = channel.of(file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/genome_gfp.gtf', checkIfExists: true))
                input[3] = 'gene_id'
                input[4] = 'gene_name'
                input[5] = 'rsem'
                input[6] = false
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(workflow.out).match() }
            )
        }
    }
}

process {
    withName: 'QUANT_TXIMPORT_SUMMARIZEDEXPERIMENT:CUSTOM_TX2GENE' {
        ext.prefix = { "${quant_type}.merged" }
    }

    withName: 'QUANT_TXIMPORT_SUMMARIZEDEXPERIMENT:TXIMETA_TXIMPORT' {
        ext.prefix = { "${quant_type}.merged" }
    }

    withName: 'QUANT_TXIMPORT_SUMMARIZEDEXPERIMENT:SE_GENE_UNIFIED' {
        ext.prefix = { "${meta.id}_gene" }
        ext.args = '--assay_names counts,counts_length_scaled,counts_scaled,lengths,tpm'
    }

    withName: 'QUANT_TXIMPORT_SUMMARIZEDEXPERIMENT:SE_TRANSCRIPT_UNIFIED' {
        ext.prefix = { "${meta.id}_transcript" }
        ext.args = '--assay_names counts,lengths,tpm'
    }
}
